Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:700;font-size:12px;color:#1c3f66">Building I for a uniform disk</span>
<p id="demoTitle" style="margin:2px 0 0;font-size:11.5px;font-weight:700;color:#8a4a22"></p>
<p id="demoNarration" style="margin:0;font-size:11px;line-height:1.45;color:#333"></p>
<span style="display:flex;gap:6px;align-items:center;margin:2px 0 4px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;color:#555"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Ring radius r / R: <output id="ringRadiusVal">0.55</output>
  <input id="ringRadiusInput" type="range" min="0.05" max="1" step="0.01" value="0.55" oninput="document.getElementById('ringRadiusVal').value=this.value;update_ringRadius(+this.value)"></label>
<label>Ring width dr / R: <output id="ringWidthVal">0.06</output>
  <input id="ringWidthInput" type="range" min="0.01" max="0.25" step="0.01" value="0.06" oninput="document.getElementById('ringWidthVal').value=this.value;update_ringWidth(+this.value)"></label>
<label>View
  <select id="viewModeInput" onchange="toggle_viewMode(this.value)">
    <option value="Face-on (x–y)">Face-on (x–y)</option>
    <option value="Perspective (tilted)">Perspective (tilted)</option>
    <option value="Both" selected>Both</option>
  </select></label>
<button id="integrateBtn" onclick="trigger_integrateRings()">Sum rings from center to rim</button>
<span id="sumReadout" style="font-size:11px;color:#444;line-height:1.4"></span>
<span style="font-size:10px;color:#777;line-height:1.35">Hover or click the ring, the disk or the bars for details.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 900, H = 496;
  draw.viewbox(0, 0, W, H);

  /* ── palette ─────────────────────────────────────────────── */
  var ORANGE = '#dd8f62';
  var ORANGE_LIGHT = '#f0b68f';
  var BLUE_OUTLINE = '#8c96b8';
  var INK = '#111111';
  var STEEL = '#4a6fa5';

  /* ── geometry ────────────────────────────────────────────── */
  var CX1 = 228, CY1 = 212, R1 = 152;                 // face-on panel
  var CX2 = 652, CY2 = 228, RX = 172, RY = 70;        // perspective panel
  var LOOP_CX = 652, LOOP_CY = 112, LOOP_RX = 56, LOOP_RY = 18;

  /* ── gradient (blue → white disk shading) ────────────────── */
  var grad = draw.gradient('radial', function (add) {
    add.stop(0, '#ffffff');
    add.stop(0.5, '#eef1f8');
    add.stop(1, '#a9b3d3');
  });
  grad.attr({ cx: 0.5, cy: 0.5, r: 0.66, fx: 0.36, fy: 0.62 });

  /* ── helpers ─────────────────────────────────────────────── */
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }
  function lbl(g, x, y, txt, size, color) {
    var t = g.text(txt);
    t.font({ family: 'Georgia, "Times New Roman", serif', size: size || 21, anchor: 'middle' });
    t.attr({ 'font-style': 'italic', 'font-weight': 'bold' });
    t.fill(color || INK);
    halo(t);
    t.center(x, y);
    return t;
  }
  function headAt(g, x, y, ang, size, color) {
    var a1 = ang + Math.PI * 0.86, a2 = ang - Math.PI * 0.86;
    g.polygon([[x, y],
    [x + size * Math.cos(a1), y + size * Math.sin(a1)],
    [x + size * Math.cos(a2), y + size * Math.sin(a2)]]).fill(color).stroke('none');
  }
  function arrow(g, x1, y1, x2, y2, color, w, both, size) {
    size = size || 8;
    g.line(x1, y1, x2, y2).stroke({ color: color, width: w || 1.3, linecap: 'round' });
    var ang = Math.atan2(y2 - y1, x2 - x1);
    headAt(g, x2, y2, ang, size, color);
    if (both) headAt(g, x1, y1, ang + Math.PI, size, color);
  }
  function annulusPath(cx, cy, rxo, ryo, rxi, ryi) {
    function ring(rx, ry) {
      return 'M' + (cx - rx) + ',' + cy +
        'A' + rx + ',' + ry + ' 0 1 0 ' + (cx + rx) + ',' + cy +
        'A' + rx + ',' + ry + ' 0 1 0 ' + (cx - rx) + ',' + cy + 'Z';
    }
    var d = ring(rxo, ryo);
    if (rxi > 0.4 && ryi > 0.2) d += ring(rxi, ryi);
    return d;
  }
  function fmt(v, n) { return v.toFixed(n); }

  /* ── layer groups ────────────────────────────────────────── */
  var gLeft = draw.group();
  var diskL = gLeft.group(), fadedL = gLeft.group(), ringL = gLeft.group(),
    axesL = gLeft.group(), annL = gLeft.group(), statL = gLeft.group();

  var gRight = draw.group();
  var diskR = gRight.group(), fadedR = gRight.group(), ringR = gRight.group(),
    axesR = gRight.group(), annR = gRight.group(), statR = gRight.group();

  var gRead = draw.group();

  /* ── static: face-on panel ───────────────────────────────── */
  var diskCircle = diskL.circle(2 * R1).center(CX1, CY1)
    .fill(grad).stroke({ color: BLUE_OUTLINE, width: 1.2 });
  diskCircle.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Uniform disk: mass M, radius R, surface density M/πR²', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The uniform disk', 'The disk has total mass M spread evenly over area πR², so every bit of area dA carries mass dm = (M/πR²) dA. Because the mass is spread over many different radii, I cannot be written as MR² — it must be integrated.');
    });

  arrow(axesL, CX1, CY1 + R1 + 24, CX1, CY1 - R1 - 34, INK, 1.3, false, 9);   // x (up)
  arrow(axesL, CX1 - R1 - 36, CY1, CX1 + R1 + 42, CY1, INK, 1.3, false, 9);   // y (right)
  lbl(statL, CX1 - 17, CY1 - R1 - 48, 'x', 21);
  lbl(statL, CX1 + R1 + 58, CY1 + 6, 'y', 21);
  lbl(statL, CX1 - 19, CY1 - 13, 'z', 20);

  // R double arrow (lower-left)
  var Rdx = -0.80, Rdy = 0.60;
  arrow(statL, CX1, CY1, CX1 + Rdx * R1, CY1 + Rdy * R1, INK, 1.2, true, 8);
  lbl(statL, CX1 + Rdx * R1 * 0.74 - 12, CY1 + Rdy * R1 * 0.74 - 12, 'R', 20);

  /* ── static: perspective panel ───────────────────────────── */
  var diskEll = diskR.ellipse(2 * RX, 2 * RY).center(CX2, CY2)
    .fill(grad).stroke({ color: ORANGE, width: 2.4 });
  diskEll.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Same disk, seen obliquely — it spins about the z axis', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Same disk, tilted view', 'The circle and the ellipse are the same object seen from two directions. The mass element we integrate is a complete ring that encircles the rotation axis — not a point and not a radial strip.');
    });

  arrow(axesR, CX2, CY2 + 92, CX2, CY2 - 158, INK, 1.3, false, 9);            // z
  arrow(axesR, CX2 - RX - 28, CY2, CX2 + RX + 40, CY2, INK, 1.3, false, 9);   // y
  arrow(axesR, CX2 + 98, CY2 - 68, CX2 - 126, CY2 + 88, INK, 1.3, false, 9);  // x (oblique)
  lbl(statR, CX2 - 18, CY2 - 174, 'z', 21);
  lbl(statR, CX2 + RX + 56, CY2 + 6, 'y', 21);
  lbl(statR, CX2 - 140, CY2 + 108, 'x', 21);

  // rotation loop (wide sweep, clear head)
  var loopPts = [];
  for (var a = 10; a <= 310; a += 4) {
    var rad = a * Math.PI / 180;
    loopPts.push([LOOP_CX + LOOP_RX * Math.cos(rad), LOOP_CY + LOOP_RY * Math.sin(rad)]);
  }
  var loop = statR.polyline(loopPts).fill('none').stroke({ color: INK, width: 1.6, linecap: 'round' });
  (function () {
    var ae = 310 * Math.PI / 180;
    headAt(statR, LOOP_CX + LOOP_RX * Math.cos(ae), LOOP_CY + LOOP_RY * Math.sin(ae),
      Math.atan2(LOOP_RY * Math.cos(ae), -LOOP_RX * Math.sin(ae)), 10, INK);
  })();
  loop.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Rotation about the z axis', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The rotation axis', 'All distances r in the integral are measured perpendicular to this z axis. A ring is special because every one of its mass points sits at exactly the same perpendicular distance r.'); });

  statR.circle(4).center(CX2, CY2).fill(INK);

  /* ── readout panel (compact, larger type) ────────────────── */
  gRead.rect(840, 84).move(30, 404).radius(6).fill('#fafbfc').stroke({ color: '#e2e6ea', width: 1 });
  function rtext(x, y, s, size, color, weight) {
    var t = gRead.text(s);
    t.font({ family: 'system-ui, sans-serif', size: size || 14, anchor: 'start' });
    t.fill(color || '#222');
    if (weight) t.attr('font-weight', weight);
    t.move(x, y);
    return t;
  }
  var tR = rtext(46, 412, '', 14, '#111', 600);
  var tDr = rtext(160, 412, '', 14, '#111', 600);
  var tDA = rtext(290, 412, '', 14);
  var tDm = rtext(500, 412, '', 14);

  var tBar1 = rtext(46, 441, '', 14);
  gRead.rect(230, 15).move(240, 441).radius(3).fill('#ececf1');
  var bar1 = gRead.rect(0, 15).move(240, 441).radius(3).fill(ORANGE);

  var tBar2 = rtext(46, 465, '', 14);
  gRead.rect(230, 15).move(240, 465).radius(3).fill('#ececf1');
  var bar2 = gRead.rect(0, 15).move(240, 465).radius(3).fill(STEEL);
  var tBar2r = rtext(480, 465, '', 12.5, '#666');

  gRead.rect(16, 11).move(600, 443).fill(ORANGE_LIGHT).stroke({ color: ORANGE, width: 1 });
  rtext(624, 440, 'ring that carries dm', 12.5, '#555');
  gRead.rect(16, 11).move(600, 467).fill('#c3cbe4').stroke({ color: BLUE_OUTLINE, width: 1 });
  rtext(624, 464, 'rest of the uniform disk', 12.5, '#555');

  [bar1, bar2].forEach(function (b) {
    b.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip(b === bar1 ? 'dI = r² dm for the highlighted ring' : 'Running total Σ r² dm, scaled against ½MR²', e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        if (b === bar1) showPopup('dI = r² dm', 'With dm = (M/πR²)·2πr dr = (2M/R²) r dr, the ring contributes dI = (2M/R²) r³ dr. The r³ is why a ring at the rim contributes enormously more than an identical-width ring near the centre.');
        else showPopup('Σ r² dm → ½MR²', 'Integrating (2M/R²) r³ dr from 0 to R gives I = ½MR². Notice how little of the total accumulates in the inner half of the disk: the inner half of the radius supplies only 1/16 of I.');
      });
  });

  /* ── state ───────────────────────────────────────────────── */
  var state = { r: 0.55, dr: 0.06, view: 'Both', sum: 0, faded: [], integrating: false, done: false, persRing: false };
  var timer = null;

  function ringGeom() {
    var outer = Math.min(1, state.r + state.dr / 2);
    var inner = Math.max(0, outer - state.dr);
    return { inner: inner, outer: outer, mid: (inner + outer) / 2, w: outer - inner };
  }

  /* ── dynamic drawing ─────────────────────────────────────── */
  function drawDynamic() {
    var g = ringGeom();
    ringL.clear(); annL.clear(); fadedL.clear();
    ringR.clear(); annR.clear(); fadedR.clear();

    // previously summed rings (faded)
    state.faded.forEach(function (f) {
      fadedL.path(annulusPath(CX1, CY1, f.o * R1, f.o * R1, f.i * R1, f.i * R1))
        .attr('fill-rule', 'evenodd').fill({ color: ORANGE_LIGHT, opacity: 0.22 })
        .stroke({ color: ORANGE, width: 0.5, opacity: 0.45 });
      fadedR.path(annulusPath(CX2, CY2, f.o * RX, f.o * RY, f.i * RX, f.i * RY))
        .attr('fill-rule', 'evenodd').fill({ color: ORANGE_LIGHT, opacity: 0.22 })
        .stroke({ color: ORANGE, width: 0.5, opacity: 0.45 });
    });

    var dmVal = 2 * g.mid * g.w;
    function wire(p) {
      p.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Ring: r = ' + fmt(g.mid, 2) + 'R, dr = ' + fmt(g.w, 3) + 'R, dm = ' + fmt(dmVal, 3) + 'M', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The ring mass element',
            'Every point of this ring lies at the same distance r from the z axis, so its whole mass dm can be multiplied by one single r²: dI = r² dm. Its area is the circumference times the width, dA = 2πr dr, giving dm = (2M/R²) r dr.');
        });
    }

    // highlighted ring — face-on (light tint, orange stroke reads as a circle)
    wire(ringL.path(annulusPath(CX1, CY1, g.outer * R1, g.outer * R1, g.inner * R1, g.inner * R1))
      .attr('fill-rule', 'evenodd')
      .fill({ color: ORANGE_LIGHT, opacity: 0.26 })
      .stroke({ color: ORANGE, width: 2.1 }));

    // highlighted ring — perspective (suppressed in the plain "whole disk" view)
    if (state.persRing) {
      wire(ringR.path(annulusPath(CX2, CY2, g.outer * RX, g.outer * RY, g.inner * RX, g.inner * RY))
        .attr('fill-rule', 'evenodd')
        .fill({ color: ORANGE_LIGHT, opacity: 0.20 })
        .stroke({ color: ORANGE, width: 2.1 }));
    }

    // r arrow (face-on, lower right)
    var ux = 0.707, uy = 0.707, rp = g.mid * R1;
    arrow(annL, CX1, CY1, CX1 + ux * rp, CY1 + uy * rp, INK, 1.2, false, 8);
    lbl(annL, CX1 + ux * rp * 0.55 + 15, CY1 + uy * rp * 0.55 - 10, 'r', 20);

    // dr arrow (face-on, upper right)
    var dx = 0.62, dy = -0.78, ro = g.outer * R1;
    var hx = CX1 + dx * (ro + 5), hy = CY1 + dy * (ro + 5);
    var tx = CX1 + dx * (ro + 62), ty = CY1 + dy * (ro + 62);
    arrow(annL, tx, ty, hx, hy, INK, 1.2, false, 8);
    lbl(annL, tx + 21, ty + 3, 'dr', 19);

    // r arrow + dm marker (perspective) — always on the OUTER edge of the element
    var edge = state.persRing ? g.outer : 1;
    var th = -35 * Math.PI / 180;
    var px = CX2 + edge * RX * Math.cos(th), py = CY2 + edge * RY * Math.sin(th);
    arrow(annR, CX2, CY2, px, py, INK, 1.2, false, 8);
    lbl(annR, CX2 + (px - CX2) * 0.56, CY2 + (py - CY2) * 0.56 - 14, 'r', 20);
    var dot = annR.circle(7).center(px, py).fill(ORANGE).stroke({ color: '#a35a2c', width: 1.1 });
    lbl(annR, px + 34, py - 20, 'dm', 19);
    dot.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('dm — the mass of the whole ring, all at radius ' + fmt(edge === 1 ? 1 : g.mid, 2) + 'R', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('dm on the ring', 'The marker sits on the ring that carries dm. Sliding around the ring never changes the distance to the z axis, so the entire dm can be multiplied by one r² — that is what makes the ring the natural mass element.');
      });
  }

  /* ── readout ─────────────────────────────────────────────── */
  function updateReadout() {
    var g = ringGeom();
    var dA = 2 * Math.PI * g.mid * g.w;        // in R²
    var dm = 2 * g.mid * g.w;                  // in M
    var dI = 2 * g.mid * g.mid * g.mid * g.w;  // in M R²
    tR.text('r/R = ' + fmt(g.mid, 2));
    tDr.text('dr/R = ' + fmt(g.w, 3));
    tDA.text('dA = 2πr dr = ' + fmt(dA, 3) + ' R²');
    tDm.text('dm = (M/πR²) dA = ' + fmt(dm, 3) + ' M');

    tBar1.text('dI = r² dm = ' + fmt(dI, 4) + ' MR²');
    var f1 = Math.max(0, Math.min(1, Math.pow(g.mid, 3)));
    bar1.width(Math.max(1, 230 * f1));

    tBar2.text('Σ r² dm = ' + fmt(state.sum, 4) + ' MR²');
    var f2 = Math.max(0, Math.min(1, state.sum / 0.5));
    bar2.width(Math.max(1, 230 * f2));
    tBar2r.text(Math.round(f2 * 100) + '% of ½MR²');

    var sr = document.getElementById('sumReadout');
    if (sr) {
      sr.textContent = 'dm = ' + fmt(dm, 3) + 'M · dI = ' + fmt(dI, 4) + 'MR²' +
        (state.sum > 0 ? '  |  Σ = ' + fmt(state.sum, 4) + 'MR² (' + Math.round(f2 * 100) + '% of ½MR²)' : '');
    }
  }

  /* ── view mode ───────────────────────────────────────────── */
  function applyView() {
    if (state.view === 'Face-on (x–y)') {
      gLeft.show(); gRight.hide();
      gLeft.transform({ translateX: 450 - CX1, translateY: 0 });
    } else if (state.view === 'Perspective (tilted)') {
      gLeft.hide(); gRight.show();
      gRight.transform({ translateX: 450 - CX2, translateY: 0 });
    } else {
      gLeft.show(); gRight.show();
      gLeft.transform({ translateX: 0, translateY: 0 });
      gRight.transform({ translateX: 0, translateY: 0 });
    }
  }

  /* ── public handlers ─────────────────────────────────────── */
  window.update_ringRadius = function (v) {
    state.r = v; state.persRing = true;
    if (!state.integrating) resetSum();
    drawDynamic(); updateReadout();
  };
  window.update_ringWidth = function (v) {
    state.dr = v; state.persRing = true;
    if (!state.integrating) resetSum();
    drawDynamic(); updateReadout();
  };
  window.toggle_viewMode = function (val) {
    state.view = val; applyView();
  };

  function resetSum() {
    if (timer) { clearInterval(timer); timer = null; }
    state.integrating = false; state.done = false;
    state.sum = 0; state.faded = [];
    var b = document.getElementById('integrateBtn');
    if (b) { b.textContent = 'Sum rings from center to rim'; b.classList.remove('active'); }
  }

  window.trigger_integrateRings = function () {
    var b = document.getElementById('integrateBtn');
    if (state.integrating) return;
    if (state.done) { resetSum(); drawDynamic(); updateReadout(); return; }
    state.sum = 0; state.faded = []; state.persRing = true;
    state.integrating = true;
    if (b) { b.textContent = 'Summing…'; b.classList.add('active'); }
    var dr = state.dr, i = 0, n = Math.ceil(1 / dr);
    timer = setInterval(function () {
      var inner = i * dr, outer = Math.min(1, (i + 1) * dr);
      var mid = (inner + outer) / 2, w = outer - inner;
      state.faded.push({ i: inner, o: outer });
      state.sum += 2 * mid * mid * mid * w;
      state.r = mid; state.dr = w;
      var ri = document.getElementById('ringRadiusInput');
      var rv = document.getElementById('ringRadiusVal');
      if (ri) ri.value = mid.toFixed(2);
      if (rv) rv.value = mid.toFixed(2);
      drawDynamic(); updateReadout();
      i++;
      if (i >= n || outer >= 1) {
        clearInterval(timer); timer = null;
        state.integrating = false; state.done = true;
        state.dr = dr;
        if (b) { b.textContent = 'Reset sum'; b.classList.remove('active'); }
        drawDynamic(); updateReadout();
      }
    }, 60);
  };

  /* ── demo steps ──────────────────────────────────────────── */
  var steps = [
    {
      title: '1. The whole disk',
      narration: 'A uniform disk of mass M and radius R spins about the z axis through its center. Seen face-on the axis points out of the page; in perspective the curved arrow shows the sense of rotation and dm marks a mass element on the rim.',
      state: { viewMode: 'Both', ringRadius: 0.55, ringWidth: 0.06, persRing: false }
    },
    {
      title: '2. Pick one thin ring',
      narration: 'Highlight a single thin annulus at radius r with width dr. In the perspective view the same ring now carries dm, and every bit of that mass sits at the same distance r from the axis.',
      state: { viewMode: 'Both', ringRadius: 0.55, ringWidth: 0.06, persRing: true }
    },
    {
      title: '3. Make the ring differential',
      narration: 'Shrink dr. The ring\u2019s area 2πr dr and its mass dm shrink with it, and the spread of radii inside the ring vanishes — this is why dI = r² dm is exact for a ring, not an approximation.',
      state: { viewMode: 'Face-on (x–y)', ringRadius: 0.55, ringWidth: 0.02, persRing: true }
    },
    {
      title: '4. Slide the ring inward',
      narration: 'Near the center the ring is short, holds little mass, and its lever arm is tiny, so its r² dm contribution is almost nothing.',
      state: { viewMode: 'Face-on (x–y)', ringRadius: 0.12, ringWidth: 0.02, persRing: true }
    },
    {
      title: '5. Slide the ring outward',
      narration: 'Push the same-width ring out to the rim: it is now long, holds far more mass, and each gram sits at the largest possible radius, so the contribution jumps dramatically.',
