      .on('mouseleave', hideTooltip)
      .on('click', function () {
        if (b === bar1) showPopup('dI = r² dm', 'With dm = (M/πR²)·2πr dr = (2M/R²) r dr, the ring contributes dI = (2M/R²) r³ dr. The r³ is why a ring at the rim contributes enormously more than an identical-width ring near the centre.');
        else showPopup('Σ r² dm → ½MR²', 'Integrating (2M/R²) r³ dr from 0 to R gives I = ½MR². Notice how little of the total accumulates in the inner half of the disk: the inner half of the radius supplies only 1/16 of I.');
      });
  });

  /* ── state ───────────────────────────────────────────────── */
  var state = { r: 0.55, dr: 0.06, view: 'Both', sum: 0, faded: [], integrating: false, done: false, persRing: false };
  var timer = null;

  function ringGeom() {
    var outer = Math.min(1, state.r + state.dr / 2);
    var inner = Math.max(0, outer - state.dr);
    return { inner: inner, outer: outer, mid: (inner + outer) / 2, w: outer - inner };
  }

  /* ── dynamic drawing ─────────────────────────────────────── */
  function drawDynamic() {
    var g = ringGeom();
    ringL.clear(); annL.clear(); fadedL.clear();
    ringR.clear(); annR.clear(); fadedR.clear();

    // previously summed rings (faded)
    state.faded.forEach(function (f) {
      fadedL.path(annulusPath(CX1, CY1, f.o * R1, f.o * R1, f.i * R1, f.i * R1))
        .attr('fill-rule', 'evenodd').fill({ color: ORANGE_LIGHT, opacity: 0.22 })
        .stroke({ color: ORANGE, width: 0.5, opacity: 0.45 });
      fadedR.path(annulusPath(CX2, CY2, f.o * RX, f.o * RY, f.i * RX, f.i * RY))
        .attr('fill-rule', 'evenodd').fill({ color: ORANGE_LIGHT, opacity: 0.22 })
        .stroke({ color: ORANGE, width: 0.5, opacity: 0.45 });
    });

    var dmVal = 2 * g.mid * g.w;
    function wire(p) {
      p.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Ring: r = ' + fmt(g.mid, 2) + 'R, dr = ' + fmt(g.w, 3) + 'R, dm = ' + fmt(dmVal, 3) + 'M', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The ring mass element',
            'Every point of this ring lies at the same distance r from the z axis, so its whole mass dm can be multiplied by one single r²: dI = r² dm. Its area is the circumference times the width, dA = 2πr dr, giving dm = (2M/R²) r dr.');
        });
    }

    // highlighted ring — face-on (light tint, orange stroke reads as a circle)
    wire(ringL.path(annulusPath(CX1, CY1, g.outer * R1, g.outer * R1, g.inner * R1, g.inner * R1))
      .attr('fill-rule', 'evenodd')
      .fill({ color: ORANGE_LIGHT, opacity: 0.26 })
      .stroke({ color: ORANGE, width: 2.1 }));

    // highlighted ring — perspective (suppressed in the plain "whole disk" view)
    if (state.persRing) {
      wire(ringR.path(annulusPath(CX2, CY2, g.outer * RX, g.outer * RY, g.inner * RX, g.inner * RY))
        .attr('fill-rule', 'evenodd')
        .fill({ color: ORANGE_LIGHT, opacity: 0.20 })
        .stroke({ color: ORANGE, width: 2.1 }));
    }

    // r arrow (face-on, lower right)
    var ux = 0.707, uy = 0.707, rp = g.mid * R1;
    arrow(annL, CX1, CY1, CX1 + ux * rp, CY1 + uy * rp, INK, 1.2, false, 8);
    lbl(annL, CX1 + ux * rp * 0.55 + 15, CY1 + uy * rp * 0.55 - 10, 'r', 20);

    // dr arrow (face-on, upper right)
    var dx = 0.62, dy = -0.78, ro = g.outer * R1;
    var hx = CX1 + dx * (ro + 5), hy = CY1 + dy * (ro + 5);
    var tx = CX1 + dx * (ro + 62), ty = CY1 + dy * (ro + 62);
    arrow(annL, tx, ty, hx, hy, INK, 1.2, false, 8);
    lbl(annL, tx + 21, ty + 3, 'dr', 19);

    // r arrow + dm marker (perspective) — always on the OUTER edge of the element
    var edge = state.persRing ? g.outer : 1;
    var th = -35 * Math.PI / 180;
    var px = CX2 + edge * RX * Math.cos(th), py = CY2 + edge * RY * Math.sin(th);
    arrow(annR, CX2, CY2, px, py, INK, 1.2, false, 8);
    lbl(annR, CX2 + (px - CX2) * 0.56, CY2 + (py - CY2) * 0.56 - 14, 'r', 20);
    var dot = annR.circle(7).center(px, py).fill(ORANGE).stroke({ color: '#a35a2c', width: 1.1 });
    lbl(annR, px + 34, py - 20, 'dm', 19);
    dot.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('dm — the mass of the whole ring, all at radius ' + fmt(edge === 1 ? 1 : g.mid, 2) + 'R', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('dm on the ring', 'The marker sits on the ring that carries dm. Sliding around the ring never changes the distance to the z axis, so the entire dm can be multiplied by one r² — that is what makes the ring the natural mass element.');
      });
  }

  /* ── readout ─────────────────────────────────────────────── */
  function updateReadout() {
    var g = ringGeom();
    var dA = 2 * Math.PI * g.mid * g.w;        // in R²
    var dm = 2 * g.mid * g.w;                  // in M
    var dI = 2 * g.mid * g.mid * g.mid * g.w;  // in M R²
    tR.text('r/R = ' + fmt(g.mid, 2));
    tDr.text('dr/R = ' + fmt(g.w, 3));
    tDA.text('dA = 2πr dr = ' + fmt(dA, 3) + ' R²');
    tDm.text('dm = (M/πR²) dA = ' + fmt(dm, 3) + ' M');

    tBar1.text('dI = r² dm = ' + fmt(dI, 4) + ' MR²');
    var f1 = Math.max(0, Math.min(1, Math.pow(g.mid, 3)));
    bar1.width(Math.max(1, 230 * f1));

    tBar2.text('Σ r² dm = ' + fmt(state.sum, 4) + ' MR²');
    var f2 = Math.max(0, Math.min(1, state.sum / 0.5));
    bar2.width(Math.max(1, 230 * f2));
    tBar2r.text(Math.round(f2 * 100) + '% of ½MR²');

    var sr = document.getElementById('sumReadout');
    if (sr) {
      sr.textContent = 'dm = ' + fmt(dm, 3) + 'M · dI = ' + fmt(dI, 4) + 'MR²' +
        (state.sum > 0 ? '  |  Σ = ' + fmt(state.sum, 4) + 'MR² (' + Math.round(f2 * 100) + '% of ½MR²)' : '');
    }
  }

  /* ── view mode ───────────────────────────────────────────── */
  function applyView() {
    if (state.view === 'Face-on (x–y)') {
      gLeft.show(); gRight.hide();
      gLeft.transform({ translateX: 450 - CX1, translateY: 0 });
    } else if (state.view === 'Perspective (tilted)') {
      gLeft.hide(); gRight.show();
      gRight.transform({ translateX: 450 - CX2, translateY: 0 });
    } else {
      gLeft.show(); gRight.show();
      gLeft.transform({ translateX: 0, translateY: 0 });
      gRight.transform({ translateX: 0, translateY: 0 });
    }
  }

  /* ── public handlers ─────────────────────────────────────── */
  window.update_ringRadius = function (v) {
    state.r = v; state.persRing = true;
    if (!state.integrating) resetSum();
    drawDynamic(); updateReadout();
  };
  window.update_ringWidth = function (v) {
    state.dr = v; state.persRing = true;
    if (!state.integrating) resetSum();
    drawDynamic(); updateReadout();
  };
  window.toggle_viewMode = function (val) {
    state.view = val; applyView();
  };

  function resetSum() {
    if (timer) { clearInterval(timer); timer = null; }
    state.integrating = false; state.done = false;
    state.sum = 0; state.faded = [];
    var b = document.getElementById('integrateBtn');
    if (b) { b.textContent = 'Sum rings from center to rim'; b.classList.remove('active'); }
  }

  window.trigger_integrateRings = function () {
    var b = document.getElementById('integrateBtn');
    if (state.integrating) return;
    if (state.done) { resetSum(); drawDynamic(); updateReadout(); return; }
    state.sum = 0; state.faded = []; state.persRing = true;
    state.integrating = true;
    if (b) { b.textContent = 'Summing…'; b.classList.add('active'); }
    var dr = state.dr, i = 0, n = Math.ceil(1 / dr);
    timer = setInterval(function () {
      var inner = i * dr, outer = Math.min(1, (i + 1) * dr);
      var mid = (inner + outer) / 2, w = outer - inner;
      state.faded.push({ i: inner, o: outer });
      state.sum += 2 * mid * mid * mid * w;
      state.r = mid; state.dr = w;
      var ri = document.getElementById('ringRadiusInput');
      var rv = document.getElementById('ringRadiusVal');
      if (ri) ri.value = mid.toFixed(2);
      if (rv) rv.value = mid.toFixed(2);
      drawDynamic(); updateReadout();
      i++;
      if (i >= n || outer >= 1) {
        clearInterval(timer); timer = null;
        state.integrating = false; state.done = true;
        state.dr = dr;
        if (b) { b.textContent = 'Reset sum'; b.classList.remove('active'); }
        drawDynamic(); updateReadout();
      }
    }, 60);
  };

  /* ── demo steps ──────────────────────────────────────────── */
  var steps = [
    {
      title: '1. The whole disk',
      narration: 'A uniform disk of mass M and radius R spins about the z axis through its center. Seen face-on the axis points out of the page; in perspective the curved arrow shows the sense of rotation and dm marks a mass element on the rim.',
      state: { viewMode: 'Both', ringRadius: 0.55, ringWidth: 0.06, persRing: false }
    },
    {
      title: '2. Pick one thin ring',
      narration: 'Highlight a single thin annulus at radius r with width dr. In the perspective view the same ring now carries dm, and every bit of that mass sits at the same distance r from the axis.',
      state: { viewMode: 'Both', ringRadius: 0.55, ringWidth: 0.06, persRing: true }
    },
    {
      title: '3. Make the ring differential',
      narration: 'Shrink dr. The ring\u2019s area 2πr dr and its mass dm shrink with it, and the spread of radii inside the ring vanishes — this is why dI = r² dm is exact for a ring, not an approximation.',
      state: { viewMode: 'Face-on (x–y)', ringRadius: 0.55, ringWidth: 0.02, persRing: true }
    },
    {
      title: '4. Slide the ring inward',
      narration: 'Near the center the ring is short, holds little mass, and its lever arm is tiny, so its r² dm contribution is almost nothing.',
      state: { viewMode: 'Face-on (x–y)', ringRadius: 0.12, ringWidth: 0.02, persRing: true }
    },
    {
      title: '5. Slide the ring outward',
      narration: 'Push the same-width ring out to the rim: it is now long, holds far more mass, and each gram sits at the largest possible radius, so the contribution jumps dramatically.',
      state: { viewMode: 'Perspective (tilted)', ringRadius: 0.95, ringWidth: 0.02, persRing: true }
    },
    {
      title: '6. Sum all the rings',
      narration: 'Add rings from the center out to R. They tile the entire disk, and the running total Σ r² dm climbs steeply only in the last part of the sweep, converging on I = ½MR².',
      state: { viewMode: 'Both', ringRadius: 1, ringWidth: 0.02, persRing: true, integrateRings: 'done' }
    }
  ];
  var cur = 0;

  function setSlider(id, val) {
    var inp = document.getElementById(id + 'Input');
    var out = document.getElementById(id + 'Val');
    if (inp) inp.value = val;
    if (out) out.value = val;
  }

  window.goStep = function (i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;

    resetSum();
    if (s.state.viewMode) {
      var sel = document.getElementById('viewModeInput');
      if (sel) sel.value = s.state.viewMode;
      state.view = s.state.viewMode;
      applyView();
    }
    state.persRing = !!s.state.persRing;
    if (s.state.ringRadius != null) { state.r = s.state.ringRadius; setSlider('ringRadius', s.state.ringRadius); }
    if (s.state.ringWidth != null) { state.dr = s.state.ringWidth; setSlider('ringWidth', s.state.ringWidth); }
    drawDynamic(); updateReadout();
    if (s.state.integrateRings === 'done') window.trigger_integrateRings();
  };
  window.nextStep = function () { goStep(cur + 1); };
  window.prevStep = function () { goStep(cur - 1); };

  /* ── init ────────────────────────────────────────────────── */
  applyView();
  drawDynamic();
  updateReadout();
  goStep(0);

  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

