  <input id="ringRadiusInput" type="range" min="0.05" max="1" step="0.01" value="0.55" oninput="document.getElementById('ringRadiusVal').value=this.value;update_ringRadius(+this.value)"></label>
<label>Ring width dr / R: <output id="ringWidthVal">0.06</output>
  <input id="ringWidthInput" type="range" min="0.01" max="0.25" step="0.01" value="0.06" oninput="document.getElementById('ringWidthVal').value=this.value;update_ringWidth(+this.value)"></label>
<label>View
  <select id="viewModeInput" onchange="toggle_viewMode(this.value)">
    <option value="Face-on (x–y)">Face-on (x–y)</option>
    <option value="Perspective (tilted)">Perspective (tilted)</option>
    <option value="Both" selected>Both</option>
  </select></label>
<button id="integrateBtn" onclick="trigger_integrateRings()">Sum rings from center to rim</button>
<span style="display:block;font-size:11.5px;color:#222;margin-top:2px">dI = r² dm = <b id="dIVal">0.0200</b> MR²</span>
<span style="display:block;height:10px;background:#ececf1;border-radius:3px;overflow:hidden"><span id="dIBar" style="display:block;height:100%;width:0%;background:#dd8f62"></span></span>
<span style="display:block;font-size:11.5px;color:#222">Σ r² dm = <b id="sumVal">0.0000</b> MR² <span id="sumPct" style="color:#666"></span></span>
<span style="display:block;height:10px;background:#ececf1;border-radius:3px;overflow:hidden"><span id="sumBar" style="display:block;height:100%;width:0%;background:#4a6fa5"></span></span>
<span style="display:block;font-size:10.5px;color:#666;line-height:1.5">
  <span style="display:inline-block;width:11px;height:9px;background:#f0b68f;border:1px solid #dd8f62"></span> ring that carries dm &nbsp;
  <span style="display:inline-block;width:11px;height:9px;background:#c3cbe4;border:1px solid #8c96b8"></span> rest of the uniform disk</span>
<span style="display:block;font-size:10px;color:#888;line-height:1.35">Hover or click the ring, the disk or the axis arrow for details.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 900, H = 470;
  draw.viewbox(0, 0, W, H);

  /* ── palette ─────────────────────────────────────────────── */
  var ORANGE = '#dd8f62';
  var ORANGE_LIGHT = '#f0b68f';
  var BLUE_OUTLINE = '#8c96b8';
  var INK = '#111111';

  /* ── geometry ────────────────────────────────────────────── */
  var CX1 = 222, CY1 = 208, R1 = 158;                  // face-on panel
  var CX2 = 648, CY2 = 225, RX = 170, RY = 70;         // perspective panel
  var LOOP_CX = 648, LOOP_CY = 106, LOOP_RX = 54, LOOP_RY = 17;

  /* ── gradient (blue → white disk shading) ────────────────── */
  var grad = draw.gradient('radial', function (add) {
    add.stop(0, '#ffffff');
    add.stop(0.5, '#eef1f8');
    add.stop(1, '#a9b3d3');
  });
  grad.attr({ cx: 0.5, cy: 0.5, r: 0.66, fx: 0.36, fy: 0.62 });

  /* ── helpers ─────────────────────────────────────────────── */
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }
  function lbl(g, x, y, txt, size, color) {
    var t = g.text(txt);
    t.font({ family: 'Georgia, "Times New Roman", serif', size: size || 21, anchor: 'middle' });
    t.attr({ 'font-style': 'italic', 'font-weight': 'bold' });
    t.fill(color || INK);
    halo(t);
    t.center(x, y);
    return t;
  }
  function headAt(g, x, y, ang, size, color) {
    var a1 = ang + Math.PI * 0.86, a2 = ang - Math.PI * 0.86;
    g.polygon([[x, y],
    [x + size * Math.cos(a1), y + size * Math.sin(a1)],
    [x + size * Math.cos(a2), y + size * Math.sin(a2)]]).fill(color).stroke('none');
  }
  function arrow(g, x1, y1, x2, y2, color, w, both, size) {
    size = size || 8;
    g.line(x1, y1, x2, y2).stroke({ color: color, width: w || 1.3, linecap: 'round' });
    var ang = Math.atan2(y2 - y1, x2 - x1);
    headAt(g, x2, y2, ang, size, color);
    if (both) headAt(g, x1, y1, ang + Math.PI, size, color);
  }
  function annulusPath(cx, cy, rxo, ryo, rxi, ryi) {
    function ring(rx, ry) {
      return 'M' + (cx - rx) + ',' + cy +
        'A' + rx + ',' + ry + ' 0 1 0 ' + (cx + rx) + ',' + cy +
        'A' + rx + ',' + ry + ' 0 1 0 ' + (cx - rx) + ',' + cy + 'Z';
    }
    var d = ring(rxo, ryo);
    if (rxi > 0.4 && ryi > 0.2) d += ring(rxi, ryi);
    return d;
  }
  function fmt(v, n) { return v.toFixed(n); }

  /* ── layer groups ────────────────────────────────────────── */
  var gLeft = draw.group();
  var diskL = gLeft.group(), fadedL = gLeft.group(), ringL = gLeft.group(),
    axesL = gLeft.group(), annL = gLeft.group(), statL = gLeft.group();

  var gRight = draw.group();
  var diskR = gRight.group(), fadedR = gRight.group(), ringR = gRight.group(),
    axesR = gRight.group(), annR = gRight.group(), statR = gRight.group();

  var gRead = draw.group();

  /* ── static: face-on panel ───────────────────────────────── */
  var diskCircle = diskL.circle(2 * R1).center(CX1, CY1)
    .fill(grad).stroke({ color: BLUE_OUTLINE, width: 1.2 });
  diskCircle.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Uniform disk: mass M, radius R, surface density M/πR²', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The uniform disk', 'The disk has total mass M spread evenly over area πR², so every bit of area dA carries mass dm = (M/πR²) dA. Because the mass sits at many different radii, I cannot be written as MR² — it must be integrated.');
    });

  arrow(axesL, CX1, CY1 + R1 + 26, CX1, CY1 - R1 - 36, INK, 1.3, false, 9);   // x (up)
  arrow(axesL, CX1 - R1 - 34, CY1, CX1 + R1 + 44, CY1, INK, 1.3, false, 9);   // y (right)
  lbl(statL, CX1 - 16, CY1 - R1 - 50, 'x', 21);
  lbl(statL, CX1 + R1 + 60, CY1 + 4, 'y', 21);
  lbl(statL, CX1 - 18, CY1 - 14, 'z', 20);

  // R double arrow (lower-left)
  var Rdx = -0.78, Rdy = 0.63;
  arrow(statL, CX1, CY1, CX1 + Rdx * R1, CY1 + Rdy * R1, INK, 1.2, true, 8);
  lbl(statL, CX1 + Rdx * R1 * 0.50 - 11, CY1 + Rdy * R1 * 0.50 - 14, 'R', 20);

  /* ── static: perspective panel ───────────────────────────── */
  var diskEll = diskR.ellipse(2 * RX, 2 * RY).center(CX2, CY2)
    .fill(grad).stroke({ color: ORANGE, width: 2.4 });
  diskEll.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Same disk, seen obliquely — it spins about the z axis', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Same disk, tilted view', 'The circle and the ellipse are the same object seen from two directions. The mass element we integrate is a complete ring encircling the rotation axis — not a point and not a radial strip.');
    });

  arrow(axesR, CX2, CY2 + 92, CX2, CY2 - 150, INK, 1.3, false, 9);            // z
  arrow(axesR, CX2 - RX - 26, CY2, CX2 + RX + 38, CY2, INK, 1.3, false, 9);   // y
  arrow(axesR, CX2 + 108, CY2 - 74, CX2 - 130, CY2 + 92, INK, 1.3, false, 9); // x (oblique)
  lbl(statR, CX2 - 18, CY2 - 166, 'z', 21);
  lbl(statR, CX2 + RX + 54, CY2 + 4, 'y', 21);
  lbl(statR, CX2 - 146, CY2 + 112, 'x', 21);

  // rotation loop around the z axis
  var loopPts = [];
  for (var a = 10; a <= 310; a += 4) {
    var rad = a * Math.PI / 180;
    loopPts.push([LOOP_CX + LOOP_RX * Math.cos(rad), LOOP_CY + LOOP_RY * Math.sin(rad)]);
  }
  var loop = statR.polyline(loopPts).fill('none').stroke({ color: INK, width: 1.6, linecap: 'round' });
  (function () {
    var ae = 310 * Math.PI / 180;
    headAt(statR, LOOP_CX + LOOP_RX * Math.cos(ae), LOOP_CY + LOOP_RY * Math.sin(ae),
      Math.atan2(LOOP_RY * Math.cos(ae), -LOOP_RX * Math.sin(ae)), 10, INK);
  })();
  loop.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Rotation about the z axis', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The rotation axis', 'All distances r in the integral are measured perpendicular to this z axis. A ring is special because every one of its mass points sits at exactly the same perpendicular distance r.'); });

  statR.circle(4).center(CX2, CY2).fill(INK);

  /* ── compact single-line readout ─────────────────────────── */
  gRead.line(40, 432, 860, 432).stroke({ color: '#e6e9ee', width: 1 });
  function rtext(x, s, size, color, weight) {
    var t = gRead.text(s);
    t.font({ family: 'system-ui, sans-serif', size: size || 15, anchor: 'start' });
    t.fill(color || '#222');
    if (weight) t.attr('font-weight', weight);
    t.move(x, 442);
    return t;
  }
  var tR = rtext(44, '', 15, '#111', 600);
  var tDr = rtext(160, '', 15, '#111', 600);
  var tDA = rtext(296, '', 15, '#333');
  var tDm = rtext(496, '', 15, '#333');
  var tDI = rtext(664, '', 15, '#9a5a2c', 600);

  /* ── state ───────────────────────────────────────────────── */
  var state = {
    r: 0.55, dr: 0.06, view: 'Both', sum: 0, faded: [],
    integrating: false, done: false, persRing: false, showBand: false
  };
  var timer = null;

  function ringGeom() {
    var outer = Math.min(1, state.r + state.dr / 2);
    var inner = Math.max(0, outer - state.dr);
    return { inner: inner, outer: outer, mid: (inner + outer) / 2, w: outer - inner };
  }

  function wireRing(p, g) {
    var dmVal = 2 * g.mid * g.w;
    p.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip('Ring: r = ' + fmt(g.mid, 2) + 'R, dr = ' + fmt(g.w, 3) + 'R, dm = ' + fmt(dmVal, 3) + 'M', e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The ring mass element',
          'Every point of this ring lies at the same distance r from the z axis, so its whole mass dm can be multiplied by one single r²: dI = r² dm. Its area is circumference × width, dA = 2πr dr, giving dm = (2M/R²) r dr.');
      });
  }

  /* ── dynamic drawing ─────────────────────────────────────── */
  function drawDynamic() {
    var g = ringGeom();
    ringL.clear(); annL.clear(); fadedL.clear();
    ringR.clear(); annR.clear(); fadedR.clear();

    // previously summed rings (faded)
    state.faded.forEach(function (f) {
      fadedL.path(annulusPath(CX1, CY1, f.o * R1, f.o * R1, f.i * R1, f.i * R1))
        .attr('fill-rule', 'evenodd').fill({ color: ORANGE_LIGHT, opacity: 0.24 })
        .stroke({ color: ORANGE, width: 0.5, opacity: 0.45 });
      fadedR.path(annulusPath(CX2, CY2, f.o * RX, f.o * RY, f.i * RX, f.i * RY))
        .attr('fill-rule', 'evenodd').fill({ color: ORANGE_LIGHT, opacity: 0.24 })
        .stroke({ color: ORANGE, width: 0.5, opacity: 0.45 });
    });

    // highlighted ring — face-on
    if (state.showBand) {
      wireRing(ringL.path(annulusPath(CX1, CY1, g.outer * R1, g.outer * R1, g.inner * R1, g.inner * R1))
        .attr('fill-rule', 'evenodd')
        .fill({ color: ORANGE_LIGHT, opacity: 0.30 })
        .stroke({ color: ORANGE, width: 1.9 }), g);
    } else {
      wireRing(ringL.circle(2 * g.mid * R1).center(CX1, CY1)
        .fill('none').stroke({ color: ORANGE, width: 2.4 }), g);
    }

    // highlighted ring — perspective (suppressed in the plain "whole disk" view)
    if (state.persRing) {
      if (state.showBand) {
        wireRing(ringR.path(annulusPath(CX2, CY2, g.outer * RX, g.outer * RY, g.inner * RX, g.inner * RY))
          .attr('fill-rule', 'evenodd')
          .fill({ color: ORANGE_LIGHT, opacity: 0.26 })
          .stroke({ color: ORANGE, width: 1.9 }), g);
      } else {
        wireRing(ringR.ellipse(2 * g.mid * RX, 2 * g.mid * RY).center(CX2, CY2)
          .fill('none').stroke({ color: ORANGE, width: 2.2 }), g);
      }
    }

    /* r arrow (face-on, lower right) */
    var ux = 0.64, uy = 0.77, rp = g.mid * R1;
    arrow(annL, CX1, CY1, CX1 + ux * rp, CY1 + uy * rp, INK, 1.2, false, 8);
    lbl(annL, CX1 + ux * rp * 0.55 + 15, CY1 + uy * rp * 0.55 - 11, 'r', 20);

    /* dr arrow (face-on, upper right) — label sits to the RIGHT of the tail */
    var dx = 0.60, dy = -0.80, ro = g.outer * R1;
    var hx = CX1 + dx * (ro + 5), hy = CY1 + dy * (ro + 5);
    var tx = CX1 + dx * (ro + 56), ty = CY1 + dy * (ro + 56);
    arrow(annL, tx, ty, hx, hy, INK, 1.2, false, 8);
    lbl(annL, tx + 23, ty + 1, 'dr', 19);

    /* r arrow to the rim + dm at the arrowhead (perspective) */
    var edge = state.persRing ? g.outer : 1;
    var th = -30 * Math.PI / 180;
    var px = CX2 + edge * RX * Math.cos(th), py = CY2 + edge * RY * Math.sin(th);
    var rArrowG = annR.group();
    arrow(rArrowG, CX2, CY2, px, py, INK, 1.2, false, 8);
    lbl(annR, CX2 + (px - CX2) * 0.55, CY2 + (py - CY2) * 0.55 + 16, 'r', 20);
    lbl(annR, px + 28, py - 20, 'dm', 19);
    rArrowG.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip('dm — the mass of the whole ring, all of it at r = ' + fmt(edge === 1 ? 1 : g.mid, 2) + 'R', e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('dm at one radius', 'The arrowhead lands on the ring that carries dm. Moving around the ring never changes the distance to the z axis, so the entire dm can be multiplied by one r² — that is what makes the ring the natural mass element.');
      });
  }

  /* ── readout ─────────────────────────────────────────────── */
  function setBar(id, frac) {
    var el = document.getElementById(id);
    if (el) el.style.width = (Math.max(0, Math.min(1, frac)) * 100).toFixed(1) + '%';
  }
  function updateReadout() {
    var g = ringGeom();
    var dA = 2 * Math.PI * g.mid * g.w;        // in R²
    var dm = 2 * g.mid * g.w;                  // in M
    var dI = 2 * g.mid * g.mid * g.mid * g.w;  // in M R²

    tR.text('r/R = ' + fmt(g.mid, 2));
    tDr.text('dr/R = ' + fmt(g.w, 3));
    tDA.text('dA = 2πr dr = ' + fmt(dA, 3) + ' R²');
    tDm.text('dm = ' + fmt(dm, 3) + ' M');
    tDI.text('dI = r² dm = ' + fmt(dI, 4) + ' MR²');

    var dIe = document.getElementById('dIVal');
    if (dIe) dIe.textContent = fmt(dI, 4);
    setBar('dIBar', Math.pow(g.mid, 3));

    var se = document.getElementById('sumVal');
    if (se) se.textContent = fmt(state.sum, 4);
    var f2 = state.sum / 0.5;
    setBar('sumBar', f2);
    var pe = document.getElementById('sumPct');
    if (pe) pe.textContent = state.sum > 0 ? '(' + Math.round(Math.min(1, f2) * 100) + '% of ½MR²)' : '';
  }

  /* ── view mode ───────────────────────────────────────────── */
  function applyView() {
    if (state.view === 'Face-on (x–y)') {
      gLeft.show(); gRight.hide();
      gLeft.transform({ translateX: 450 - CX1, translateY: 0 });
    } else if (state.view === 'Perspective (tilted)') {
      gLeft.hide(); gRight.show();
      gRight.transform({ translateX: 450 - CX2, translateY: 0 });
    } else {
      gLeft.show(); gRight.show();
      gLeft.transform({ translateX: 0, translateY: 0 });
      gRight.transform({ translateX: 0, translateY: 0 });
    }
  }

  /* ── public handlers ─────────────────────────────────────── */
  window.update_ringRadius = function (v) {
    state.r = v; state.persRing = true;
    if (!state.integrating) resetSum();
    drawDynamic(); updateReadout();
  };
  window.update_ringWidth = function (v) {
    state.dr = v; state.persRing = true; state.showBand = true;
    if (!state.integrating) resetSum();
    drawDynamic(); updateReadout();
  };
  window.toggle_viewMode = function (val) {
    state.view = val; applyView();
  };

  function resetSum() {
    if (timer) { clearInterval(timer); timer = null; }
    state.integrating = false; state.done = false;
    state.sum = 0; state.faded = [];
    var b = document.getElementById('integrateBtn');
    if (b) { b.textContent = 'Sum rings from center to rim'; b.classList.remove('active'); }
  }

  window.trigger_integrateRings = function () {
    var b = document.getElementById('integrateBtn');
    if (state.integrating) return;
    if (state.done) { resetSum(); drawDynamic(); updateReadout(); return; }
    state.sum = 0; state.faded = []; state.persRing = true; state.showBand = true;
    state.integrating = true;
    if (b) { b.textContent = 'Summing…'; b.classList.add('active'); }
    var dr = state.dr, i = 0, n = Math.ceil(1 / dr);
    timer = setInterval(function () {
      var inner = i * dr, outer = Math.min(1, (i + 1) * dr);
      var mid = (inner + outer) / 2, w = outer - inner;
      state.faded.push({ i: inner, o: outer });
      state.sum += 2 * mid * mid * mid * w;
      state.r = mid; state.dr = w;
      var ri = document.getElementById('ringRadiusInput');
      var rv = document.getElementById('ringRadiusVal');
      if (ri) ri.value = mid.toFixed(2);
      if (rv) rv.value = mid.toFixed(2);
      drawDynamic(); updateReadout();
      i++;
      if (i >= n || outer >= 1) {
        clearInterval(timer); timer = null;
        state.integrating = false; state.done = true;
        state.dr = dr;
        if (b) { b.textContent = 'Reset sum'; b.classList.remove('active'); }
        drawDynamic(); updateReadout();
      }
    }, 60);
  };

  /* ── demo steps ──────────────────────────────────────────── */
  var steps = [
    {
      title: '1. The whole disk',
      narration: 'A uniform disk of mass M and radius R spins about the z axis through its center. Face-on, the axis points out of the page; in perspective the curved arrow gives the sense of rotation and the arrow to the rim marks a mass element dm.',
      state: { viewMode: 'Both', ringRadius: 0.55, ringWidth: 0.06, persRing: false, showBand: false }
    },
    {
      title: '2. Pick one thin ring',
      narration: 'Give the ring a real width dr. The band is now an annulus of area 2πr dr; in the perspective view the same ring carries dm, and every bit of that mass sits at the same distance r from the axis.',
      state: { viewMode: 'Both', ringRadius: 0.55, ringWidth: 0.06, persRing: true, showBand: true }
    },
    {
      title: '3. Make the ring differential',
      narration: 'Shrink dr. The ring\u2019s area and mass shrink with it, and the spread of radii inside the ring vanishes — this is why dI = r² dm is exact for a ring, not an approximation.',
      state: { viewMode: 'Face-on (x–y)', ringRadius: 0.55, ringWidth: 0.02, persRing: true, showBand: true }
    },
    {
      title: '4. Slide the ring inward',
      narration: 'Near the center the ring is short, holds little mass, and its lever arm is tiny, so its r² dm contribution is almost nothing — watch the dI bar collapse.',
      state: { viewMode: 'Face-on (x–y)', ringRadius: 0.12, ringWidth: 0.02, persRing: true, showBand: true }
    },
    {
      title: '5. Slide the ring outward',
      narration: 'Push the same-width ring out to the rim: it is longer, holds far more mass, and each gram sits at the largest possible radius, so dI = r² dm jumps by a factor of several hundred.',
      state: { viewMode: 'Perspective (tilted)', ringRadius: 0.95, ringWidth: 0.02, persRing: true, showBand: true }
    },
    {
      title: '6. Sum all the rings',
      narration: 'Add rings from the center out to R. They tile the whole disk, and the running total Σ r² dm climbs steeply only in the last part of the sweep, converging on I = ½MR².',
      state: { viewMode: 'Both', ringRadius: 1, ringWidth: 0.02, persRing: true, showBand: true, integrateRings: 'done' }
    }
  ];
  var cur = 0;

  function setSlider(id, val) {
    var inp = document.getElementById(id + 'Input');
    var out = document.getElementById(id + 'Val');
    if (inp) inp.value = val;
    if (out) out.value = val;
  }

  window.goStep = function (i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;

    resetSum();
    if (s.state.viewMode) {
      var sel = document.getElementById('viewModeInput');
      if (sel) sel.value = s.state.viewMode;
      state.view = s.state.viewMode;
      applyView();
    }
    state.persRing = !!s.state.persRing;
    state.showBand = !!s.state.showBand;
    if (s.state.ringRadius != null) { state.r = s.state.ringRadius; setSlider('ringRadius', s.state.ringRadius); }
    if (s.state.ringWidth != null) { state.dr = s.state.ringWidth; setSlider('ringWidth', s.state.ringWidth); }
    drawDynamic(); updateReadout();
    if (s.state.integrateRings === 'done') window.trigger_integrateRings();
  };
  window.nextStep = function () { goStep(cur + 1); };
  window.prevStep = function () { goStep(cur - 1); };

  /* ── init ────────────────────────────────────────────────── */
  applyView();
  drawDynamic();
  updateReadout();
  goStep(0);

  window.__markRendered();
})();
// @FIGURE_CODE_END

